namespace sv_0b26a2b2a2db48449d1955fb72495780.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_0b26a2b2a2db48449d1955fb72495780.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step @status" @onclick="() => HandleStepClick(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-icon">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_0b26a2b2a2db48449d1955fb72495780.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" /> Current position
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task Update(WorkEntryModel updated) => await OnChanged.InvokeAsync(updated);

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await Update(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }
}

@namespace sv_0b26a2b2a2db48449d1955fb72495780.Components.Pages.Apply

<fieldset class="reference-form">
    <legend>Reference @(Index + 1)</legend>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name" @onchange="e => Update(Entry with { Name = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship" @onchange="e => Update(Entry with { Relationship = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="e => Update(Entry with { Email = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone" @onchange="e => Update(Entry with { Phone = (string?)e.Value ?? string.Empty })" />
