        <input type="text" value="@Model.FullName" @onchange="e => Model = Model with { FullName = (string?)e.Value ?? string.Empty }" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Model.Email" @onchange="e => Model = Model with { Email = (string?)e.Value ?? string.Empty }" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <span class="field-error">@emailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Model.Phone" @onchange="e => Model = Model with { Phone = (string?)e.Value ?? string.Empty }" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address" @onchange="e => Model = Model with { Address = (string?)e.Value ?? string.Empty }"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @(isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfoModel> ModelChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? validationMessage;
    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        validationMessage = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            validationMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }

            await ModelChanged.InvokeAsync(Model);
            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}
"}

{"path": "/tmp/sv-0b26a2b2a2db48449d1955fb72495780/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_0b26a2b2a2db48449d1955fb72495780.Components.Pages.Apply

<div class="step-content">
