<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" /> Current position
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
