arguments.file_text:
namespace sv_0b26a2b2a2db48449d1955fb72495780.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_0b26a2b2a2db48449d1955fb72495780.Services
@namespace sv_0b26a2b2a2db48449d1955fb72495780.Components.Pages.Apply

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="job-application">
    <h1>Job Application</h1>

    @if (submittedId.HasValue)
    {
        <div class="submission-confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is <strong>#@submittedId</strong>.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@currentStep"
                       CompletedSteps="@completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="@personalInfo"
                                  ModelChanged="m => personalInfo = m"
                                  OnNext="() => AdvanceStep(0)"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 EntriesChanged="e => workEntries = e"
                                 OnNext="() => AdvanceStep(1)"
                                 OnBack="() => GoToStep(0)" />
                break;
            case 2:
                <ReferencesStep References="@references"
                                ReferencesChanged="r => references = r"
                                OnNext="() => AdvanceStep(2)"
                                OnBack="() => GoToStep(1)" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 CoverLetterChanged="c => coverLetter = c"
                                 OnNext="() => AdvanceStep(3)"
                                 OnBack="() => GoToStep(2)" />
                break;
            case 4:
                <ReviewStep Personal="@personalInfo"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnEdit="GoToStep"
                            OnBack="() => GoToStep(3)"
                            OnSubmit="SubmitApplication"
                            OnSubmitted="id => submittedId = id" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private int? submittedId;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = string.Empty;

    private void AdvanceStep(int completedStep)
    {
        completedSteps.Add(completedStep);
        currentStep = completedStep + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.job-application {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.5rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step-indicator .step.active {
    opacity: 1;
    font-weight: bold;
}

.step-indicator .step.completed {
    opacity: 1;
    cursor: pointer;
}

.step-indicator .step-icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.875rem;
    margin-bottom: 0.25rem;
}

.step-indicator .step.active .step-icon {
    background: #1a73e8;
    color: white;
}

.step-indicator .step.completed .step-icon {
