toolArgs.file_text:
.job-application {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.5rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step-indicator .step.active {
    opacity: 1;
    font-weight: bold;
}

.step-indicator .step.completed {
    opacity: 1;
    cursor: pointer;
}

.step-indicator .step-icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.875rem;
    margin-bottom: 0.25rem;
}

.step-indicator .step.active .step-icon {
    background: #1a73e8;
    color: white;
}

.step-indicator .step.completed .step-icon {
    background: #34a853;
    color: white;
}

.step-indicator .step-label {
    font-size: 0.75rem;
    text-align: center;
}

/* Form groups */
.step-content h2 {
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    gap: 1rem;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-primary {
    background: #1a73e8;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-primary:hover:not(:disabled) {
    background: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #1a73e8;
    border: 1px solid #1a73e8;
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-secondary {
    background: #f1f3f4;
    color: #333;
    border: 1px solid #dadce0;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    margin-top: 1rem;
}

.btn-danger {
    background: white;
    color: #d93025;
    border: 1px solid #d93025;
    padding: 0.375rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.875rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #dadce0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Validation */
.validation-error {
    color: #d93025;
    background: #fce8e6;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

.field-error {
    color: #d93025;
    font-size: 0.875rem;
    margin-top: 0.25rem;
    display: block;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.875rem;
    color: #666;
    margin-top: 0.25rem;
}

.hint {
    color: #666;
    margin-bottom: 1rem;
}

/* Review */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section h3 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 0 0 0.75rem;
}

.review-section h3 a {
    font-size: 0.875rem;
    font-weight: normal;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
    background: #e6f4ea;
    border-radius: 8px;
}

.submission-confirmation h2 {
    color: #34a853;
}

